@Component("building-handler")
@ProcessingGroup("building-processing-group")
public class BuildingEventHandler {
	
	// core constructor
	BuildingEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBuildingEvent
     */
    @EventHandler
    public void handle( CreateBuildingEvent event) {
        entityManager.persist(new Building(event.getBuildingId(), event.getName(), event.getSite(), event.getFloors()));
    }

    /*
     * @param	event UpdateBuildingEvent
     */
    @EventHandler
    public Building handle( UpdateBuildingEvent event) {
    	entityManager.merge(new Building(event.getBuildingId(), event.getName(), event.getSite(), event.getFloors()));
    }
    
    /*
     * @param	event DeleteBuildingEvent
     */
    @EventHandler
    public void on( DeleteBuildingEvent event) {
    	Building entity = new Building();
   
    	// ------------------------------------------
    	// apply the BuildingId
    	// ------------------------------------------
    	entity.setBuildingId( event.getBuildingId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BuildingRepository buildingEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BuildingEventHandler.class.getName());

}
